using System;
using System.Collections.Generic;
using System.Linq;
using ProcSense.Core.Content;

namespace ProcSense.Core.Flow
{
    /// <summary>One line of content/ui/case_catalogue.json (P3-SCN-02): what the scenario picker may choose from. The status is the case file's own; the catalogue approves nothing.</summary>
    public sealed record CatalogueEntry(string Id, string Procedure, string Tier, string Status, bool Stacked, string Setting, string Sex, string AgeBand, string Label, string AvatarProfile);

    /// <summary>The case catalogue the headset reads (generated by tools/content/case_catalogue.py from the case files).</summary>
    public sealed class CaseCatalogue
    {
        public const string Cholecystectomy = "cholecystectomy", Appendicectomy = "appendicectomy";

        public IReadOnlyList<CatalogueEntry> Entries { get; }
        public CaseCatalogue(IEnumerable<CatalogueEntry> entries) => Entries = entries.OrderBy(e => e.Id, StringComparer.Ordinal).ToList();

        public static CaseCatalogue Parse(string json)
        {
            var root = new JsonObj(MiniJson.Parse(json), "case_catalogue");
            var list = new List<CatalogueEntry>();
            var rows = root.Arr("cases");
            for (int i = 0; i < rows.Count; i++)
            {
                var o = new JsonObj(rows[i], JsonObj.Index("case_catalogue.cases", i));
                list.Add(new CatalogueEntry(o.Str("id"), o.Str("procedure"), o.Str("tier"), o.Str("status"), o.Bool("stacked"), o.Str("setting"), o.Str("sex"), o.Str("age_band"), o.Str("label"), o.Str("avatar_profile")));
            }
            return new CaseCatalogue(list);
        }

        public CatalogueEntry? Find(string id) => Entries.FirstOrDefault(e => e.Id == id);

        /// <summary>How many cases the mode may play for a procedure (the number on a procedure card): never a draft, never below the mode's review status.</summary>
        public int Count(SessionMode mode, string procedure) => Entries.Count(e => e.Procedure == procedure && ContentGate.Allows(e.Status, mode));
    }
}
